@import "@fontsource-variable/geist";
@import "@fontsource-variable/geist-mono";

/* Halo Dental: warm stone paper (#f5f1ee), pure white cards (#ffffff), pure black ink (#000000),
   vivid orange primary (#ff5e2b) with black label text, and amber-to-vermilion display gradient. */
:root {
  --background: oklch(0.962 0.006 56);
  --foreground: oklch(0 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.676 0.212 35.8);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.922 0.006 56);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.922 0.006 56);
  --muted-foreground: oklch(0.45 0.012 34);
  --accent: oklch(0.922 0.006 56);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.568 0.215 27.5);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 30%);
  --input: oklch(0 0 0 / 30%);
  --ring: oklch(0.676 0.212 35.8);

  --surface-raised: oklch(1 0 0);
  --surface-glass: oklch(1 0 0 / 80%);
  --highlight: oklch(0.793 0.168 70.5);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.638 0.236 28.5);

  --typeface-display: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-body: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, monospace;

  --radius: 0.25rem;
  --page-width: 90rem;
  --page-gutter: clamp(1.3rem, 2.78vw, 2.5rem);
  --section-y: clamp(3.875rem, 8.33vw, 7.5rem);

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --duration-fast: 150ms;
  --duration-normal: 300ms;
  --duration-slow: 600ms;

  --chart-1: oklch(0.676 0.212 35.8);
  --chart-2: oklch(0.793 0.168 70.5);
  --chart-3: oklch(0.638 0.236 28.5);
  --chart-4: oklch(0.532 0.246 264);
  --chart-5: oklch(0.648 0.014 34);

  --sidebar: oklch(0.962 0.006 56);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.676 0.212 35.8);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.922 0.006 56);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0 0 0 / 20%);
  --sidebar-ring: oklch(0.676 0.212 35.8);
}

/* Dark mode (and forced-dark bands: hero, mission, footer): pure black #000000 canvas,
   #0a0a0a / #241f1f raised surfaces, white text, and the same #ff5e2b orange primary. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.145 0 0);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.145 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.676 0.212 35.8);
  --primary-foreground: oklch(0 0 0);
  --secondary: oklch(0.245 0.01 18);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.245 0.01 18);
  --muted-foreground: oklch(0.648 0.014 34);
  --accent: oklch(0.245 0.01 18);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.65 0.22 27.5);
  --destructive-foreground: oklch(0 0 0);
  --border: oklch(1 0 0 / 25%);
  --input: oklch(1 0 0 / 25%);
  --ring: oklch(0.676 0.212 35.8);

  --surface-raised: oklch(0.245 0.01 18);
  --surface-glass: oklch(1 0 0 / 10%);
  --highlight: oklch(0.793 0.168 70.5);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.638 0.236 28.5);

  --chart-1: oklch(0.676 0.212 35.8);
  --chart-2: oklch(0.793 0.168 70.5);
  --chart-3: oklch(0.638 0.236 28.5);
  --chart-4: oklch(0.532 0.246 264);
  --chart-5: oklch(0.648 0.014 34);

  --sidebar: oklch(0.145 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.676 0.212 35.8);
  --sidebar-primary-foreground: oklch(0 0 0);
  --sidebar-accent: oklch(0.245 0.01 18);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 20%);
  --sidebar-ring: oklch(0.676 0.212 35.8);
}
